 $(document).ready(function() {
 if($('.g-recaptcha').length > 1){
 $('.g-recaptcha').not(':first').remove();
 }
 });

 .grecaptcha-badge {
 z-index:999999999 !important;
 }

 פוסטים 
אחרונים:

- כאבי ראש- מיגרנות כאבי ראש כרוניים מלווים חלק גדול מהאוכלוסיה בחיי היומיום שלהם. כאבי הראש עלולים להוות מטרד רציני, ולהפריע למהלך היומיום המשך לקרוא "כאבי ראש- מיגרנות" 

- מערכת עיכול על פי הרפואה הסינית מערכת העיכול שלנו מספרת בצורה ברורה מה קורה לנו בגוף.מתי אנחנו בסטרס, מה המזונות שמתאימים המשך לקרוא "מערכת עיכול" 

- מחלות אוטואימוניות קבוצת המחלות האוטואימוניות כוללת בתוכה מחלות מסוגים שונים שבכולן הגוף תוקף את עצמו.קבוצת המחלות כוללת מחלות כמו- בלוטת תריס-האשימוטו, המשך לקרוא "מחלות אוטואימוניות" 

- אבחון לשון מה אני לומדת מהלשון?המון.הלשון היא חלק חשוב באבחון האדם ברפואה הסינית.הסינים חילקו את הלשון למפה של איברים, כל איזור המשך לקרוא "אבחון לשון" 

- אבחון דופק יש לך דופק?מעולה! דופק הוא כלי אבחוני חשוב מאד!את אבחנת הדופק מבצעים על החלק הפנימי של היד.בתחילת כל טיפול המשך לקרוא "אבחון דופק"

